public java.util.List<String> core_toAllWithByNames(AST<?, ?, ?> ast, AnnotationValues<Accessors> accessors, CharSequence fieldName, boolean isBoolean) {
		java.util.List<String> in = core_toAllAccessorNames(ast, accessors, fieldName, isBoolean, "with", "with", false);
		if (!(in instanceof ArrayList)) in = new ArrayList<String>(in);
		for (int i = 0; i < in.size(); i++) in.set(i, in.get(i) + "By");
		return in;
	}

public java.util.List<String> core_toAllAccessorNames(AST<?, ?, ?> ast, AnnotationValues<Accessors> accessors, CharSequence fieldName, boolean isBoolean,
			String booleanPrefix, String normalPrefix, boolean adhereToFluent) {

		if (Boolean.TRUE.equals(ast.readConfiguration(ConfigurationKeys.GETTER_CONSEQUENT_BOOLEAN))) isBoolean = false;
		if (!isBoolean) {
			String accessorName = core_toAccessorName(ast, accessors, fieldName, false, booleanPrefix, normalPrefix, adhereToFluent);
			return (accessorName == null) ? Collections.<String>emptyList() : Collections.singletonList(accessorName);
		}

		boolean explicitPrefix = accessors != null && accessors.isExplicit("prefix");
		boolean explicitFluent = accessors != null && accessors.isExplicit("fluent");

		Accessors ac = (explicitPrefix || explicitFluent) ? accessors.getInstance() : null;

		java.util.List<String> prefix = explicitPrefix ? Arrays.asList(ac.prefix()) : ast.readConfiguration(ConfigurationKeys.ACCESSORS_PREFIX);
		boolean fluent = explicitFluent ? ac.fluent() : Boolean.TRUE.equals(ast.readConfiguration(ConfigurationKeys.ACCESSORS_FLUENT));
		CapitalizationStrategy capitalizationStrategy = ast.readConfigurationOr(ConfigurationKeys.ACCESSORS_JAVA_BEANS_SPEC_CAPITALIZATION, CapitalizationStrategy.defaultValue());

		fieldName = core_removePrefix(fieldName, prefix);
		if (fieldName == null) return Collections.emptyList();

		java.util.List<String> baseNames = core_toBaseNames(fieldName, isBoolean, fluent);

		Set<String> names = new HashSet<String>();
		for (String baseName : baseNames) {
			if (adhereToFluent && fluent) {
				names.add(baseName);
			} else {
				names.add(core_buildAccessorName(normalPrefix, baseName, capitalizationStrategy));
				if (!normalPrefix.equals(booleanPrefix)) names.add(core_buildAccessorName(booleanPrefix, baseName, capitalizationStrategy));
			}
		}

		return new ArrayList<String>(names);
	}

public java.util.List<String> core_toBaseNames(CharSequence fieldName, boolean isBoolean, boolean fluent) {
		java.util.List<String> baseNames = new ArrayList<String>();
		baseNames.add(fieldName.toString());

		// isPrefix = field is called something like 'isRunning', so 'running' could also be the fieldname.
		String fName = fieldName.toString();
		if (fName.startsWith("is") && fName.length() > 2 && !Character.isLowerCase(fName.charAt(2))) {
			String baseName = fName.substring(2);
			if (fluent) {
				baseNames.add("" + Character.toLowerCase(baseName.charAt(0)) + baseName.substring(1));
			} else {
				baseNames.add(baseName);
			}
		}

		return baseNames;
	}

public String core_buildAccessorName(AST<?, ?, ?> ast, String prefix, String suffix) {
		CapitalizationStrategy capitalizationStrategy = ast.readConfigurationOr(ConfigurationKeys.ACCESSORS_JAVA_BEANS_SPEC_CAPITALIZATION, CapitalizationStrategy.defaultValue());
		return core_buildAccessorName(prefix, suffix, capitalizationStrategy);
	}

public String core_buildAccessorName(LombokNode<?, ?, ?> node, String prefix, String suffix) {
		CapitalizationStrategy capitalizationStrategy = node.getAst().readConfigurationOr(ConfigurationKeys.ACCESSORS_JAVA_BEANS_SPEC_CAPITALIZATION, CapitalizationStrategy.defaultValue());
		return core_buildAccessorName(prefix, suffix, capitalizationStrategy);
	}

public String core_buildAccessorName(String prefix, String suffix, CapitalizationStrategy capitalizationStrategy) {
		if (suffix.length() == 0) return prefix;
		if (prefix.length() == 0) return suffix;
		return prefix + capitalizationStrategy.capitalize(suffix);
	}

public String core_camelCaseToConstant(String fieldName) {
		if (fieldName == null || fieldName.isEmpty()) return "";
		StringBuilder b = new StringBuilder();
		b.append(Character.toUpperCase(fieldName.charAt(0)));
		for (int i = 1; i < fieldName.length(); i++) {
			char c = fieldName.charAt(i);
			if (Character.isUpperCase(c)) b.append('_');
			b.append(Character.toUpperCase(c));
		}
		return b.toString();
	}

public int core_defaultEqualsAndHashcodeIncludeRank(String typeName) {
		// Modification in this code should be documented
		// 1. In the changelog this should be marked as an INPROBABLE BREAKING CHANGE, since the hashcode will change
		// 2. In the javadoc of EqualsAndHashcode.Include#rank
		if (JavaIdentifiers.isPrimitive(typeName)) return 1000;
		if (PRIMITIVE_WRAPPER_TYPE_NAME_PATTERN.matcher(typeName).matches()) return 800;
		return 0;
	}

public String core_stripLinesWithTagFromJavadoc(String javadoc, JavadocTag tag) {
		if (javadoc == null || javadoc.isEmpty()) return javadoc;
		return tag.getPattern().matcher(javadoc).replaceAll("").trim();
	}

public String core_stripSectionsFromJavadoc(String javadoc) {
		if (javadoc == null || javadoc.isEmpty()) return javadoc;
		Matcher sectionMatcher = SECTION_FINDER.matcher(javadoc);
		if (!sectionMatcher.find()) return javadoc;

		return javadoc.substring(0, sectionMatcher.start());
	}

public String core_getJavadocSection(String javadoc, String sectionNameSpec) {
		if (javadoc == null || javadoc.isEmpty()) return null;
		String[] sectionNames = sectionNameSpec.split("\\|");
		Matcher sectionMatcher = SECTION_FINDER.matcher(javadoc);
		Matcher lineBreakMatcher = LINE_BREAK_FINDER.matcher(javadoc);
		int sectionStart = -1;
		int sectionEnd = -1;
		while (sectionMatcher.find()) {
			boolean found = false;
			for (String sectionName : sectionNames) if (sectionMatcher.group(1).equalsIgnoreCase(sectionName)) {
				found = true;
				break;
			}
			if (found) {
				lineBreakMatcher.find(sectionMatcher.end());
				sectionStart = lineBreakMatcher.end();
			} else if (sectionStart != -1) {
				sectionEnd = sectionMatcher.start();
			}
		}

		if (sectionStart != -1) {
			if (sectionEnd != -1) return javadoc.substring(sectionStart, sectionEnd);
			return javadoc.substring(sectionStart);
		}

		return null;
	}

public String core_addReturnsThisIfNeeded(String in) {
		if (in != null && FIND_RETURN.matcher(in).find()) return in;

		return core_addJavadocLine(in, "@return {@code this}.");
	}

public String core_addReturnsUpdatedSelfIfNeeded(String in) {
		if (in != null && FIND_RETURN.matcher(in).find()) return in;

		return core_addJavadocLine(in, "@return a clone of this object, except with this updated property (returns {@code this} if an identical value is passed).");
	}

public String core_addJavadocLine(String in, String line) {
		if (in == null) return line;
		if (in.endsWith("\n")) return in + line + "\n";
		return in + "\n" + line;
	}

public String core_getParamJavadoc(String methodComment, String param) {
		if (methodComment == null || methodComment.isEmpty()) return methodComment;
		Pattern pattern = Pattern.compile("@param " + param + " (\\S|\\s)+?(?=^ ?@)", Pattern.MULTILINE | Pattern.CASE_INSENSITIVE);
		Matcher matcher = pattern.matcher(methodComment);
		if (matcher.find()) {
			return matcher.group();
		}
		return null;
	}

public void javacGetter_generateGetterForType(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelGetter, List<JCAnnotation> onMethod) {
		if (checkForTypeLevelGetter) {
			if (hasAnnotation(Getter.class, typeNode)) {
				//The annotation will make it happen, so we can skip it.
				return;
			}
		}

		if (!isClassOrEnum(typeNode)) {
			errorNode.addError(GETTER_NODE_NOT_SUPPORTED_ERR);
			return;
		}

		for (JavacNode field : typeNode.down()) {
			if (javacGetter_fieldQualifiesForGetterGeneration(field)) javacGetter_generateGetterForField(field, errorNode.get(), level, false, onMethod);
		}
	}

public boolean javacGetter_fieldQualifiesForGetterGeneration(JavacNode field) {
		if (field.getKind() != Kind.FIELD) return false;
		JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
		//Skip fields that start with $
		if (fieldDecl.name.toString().startsWith("$")) return false;
		//Skip static fields.
		if ((fieldDecl.mods.flags & Flags.STATIC) != 0) return false;
		return true;
	}

public void javacGetter_generateGetterForField(JavacNode fieldNode, DiagnosticPosition pos, AccessLevel level, boolean lazy, List<JCAnnotation> onMethod) {
		if (hasAnnotation(Getter.class, fieldNode)) {
			//The annotation will make it happen, so we can skip it.
			return;
		}
		javacGetter_createGetterForField(level, fieldNode, fieldNode, false, lazy, onMethod);
	}

public void javacGetter_handle(AnnotationValues<Getter> annotation, JCAnnotation ast, JavacNode annotationNode) {
		lastGetterNode = annotationNode;

		handleFlagUsage(annotationNode, ConfigurationKeys.GETTER_FLAG_USAGE, "@Getter");

		Collection<JavacNode> fields = annotationNode.upFromAnnotationToFields();
		deleteAnnotationIfNeccessary(annotationNode, Getter.class);
		deleteImportFromCompilationUnit(annotationNode, "lombok.AccessLevel");
		JavacNode node = annotationNode.up();
		Getter annotationInstance = annotation.getInstance();
		AccessLevel level = annotationInstance.value();
		boolean lazy = annotationInstance.lazy();
		if (lazy) handleFlagUsage(annotationNode, ConfigurationKeys.GETTER_LAZY_FLAG_USAGE, "@Getter(lazy=true)");

		if (level == AccessLevel.NONE) {
			if (lazy) annotationNode.addWarning("'lazy' does not work with AccessLevel.NONE.");
			return;
		}

		if (node == null) return;

		List<JCAnnotation> onMethod = unboxAndRemoveAnnotationParameter(ast, "onMethod", "@Getter(onMethod", annotationNode);

		switch (node.getKind()) {
		case FIELD:
			javacGetter_createGetterForFields(level, fields, annotationNode, true, lazy, onMethod);
			break;
		case TYPE:
			if (lazy) annotationNode.addError("'lazy' is not supported for @Getter on a type.");
			javacGetter_generateGetterForType(node, annotationNode, level, false, onMethod);
			break;
		}
	}

public void javacGetter_createGetterForFields(AccessLevel level, Collection<JavacNode> fieldNodes, JavacNode errorNode, boolean whineIfExists, boolean lazy, List<JCAnnotation> onMethod) {
		for (JavacNode fieldNode : fieldNodes) {
			javacGetter_createGetterForField(level, fieldNode, errorNode, whineIfExists, lazy, onMethod);
		}
	}

public void javacGetter_createGetterForField(AccessLevel level,
			JavacNode fieldNode, JavacNode source, boolean whineIfExists, boolean lazy, List<JCAnnotation> onMethod) {

		if (fieldNode.getKind() != Kind.FIELD) {
			source.addError(GETTER_NODE_NOT_SUPPORTED_ERR);
			return;
		}

		JCVariableDecl fieldDecl = (JCVariableDecl) fieldNode.get();

		if (lazy) {
			if ((fieldDecl.mods.flags & Flags.PRIVATE) == 0 || (fieldDecl.mods.flags & Flags.FINAL) == 0) {
				source.addError("'lazy' requires the field to be private and final.");
				return;
			}
			if ((fieldDecl.mods.flags & Flags.TRANSIENT) != 0) {
				source.addError("'lazy' is not supported on transient fields.");
				return;
			}
			if (fieldDecl.init == null) {
				source.addError("'lazy' requires field initialization.");
				return;
			}
		}

		AnnotationValues<Accessors> accessors = getAccessorsForField(fieldNode);
		String methodName = toGetterName(fieldNode, accessors);

		if (methodName == null) {
			source.addWarning("Not generating getter for this field: It does not fit your @Accessors prefix list.");
			return;
		}

		for (String altName : toAllGetterNames(fieldNode, accessors)) {
			switch (methodExists(altName, fieldNode, false, 0)) {
			case EXISTS_BY_LOMBOK:
				return;
			case EXISTS_BY_USER:
				if (whineIfExists) {
					String altNameExpl = "";
					if (!altName.equals(methodName)) altNameExpl = String.format(" (%s)", altName);
					source.addWarning(
						String.format("Not generating %s(): A method with that name already exists%s", methodName, altNameExpl));
				}
				return;
			default:
			case NOT_EXISTS:
				//continue scanning the other alt names.
			}
		}

		long access = toJavacModifier(level) | (fieldDecl.mods.flags & Flags.STATIC);

		injectMethod(fieldNode.up(), javacGetter_createGetter(access, fieldNode, fieldNode.getTreeMaker(), source, lazy, onMethod));
	}

public JCTree.JCMethodDecl javacGetter_createGetter(long access, JavacNode field, JavacTreeMaker treeMaker, JavacNode source, boolean lazy, List<JCAnnotation> onMethod) {
		JCVariableDecl fieldNode = (JCVariableDecl) field.get();

		// Remember the type; lazy will change it
		JCExpression methodType = javacGetter_copyType(treeMaker, fieldNode, source);
		AnnotationValues<Accessors> accessors = JavacHandlerUtil.getAccessorsForField(field);
		// Generate the methodName; lazy will change the field type
		Name methodName = field.toName(toGetterName(field, accessors));
		boolean makeFinal = shouldMakeFinal(field, accessors);

		List<JCStatement> statements;
		JCTree toClearOfMarkers = null;
		int[] methodArgPos = null;
		boolean addSuppressWarningsUnchecked = false;
		if (lazy && !inNetbeansEditor(field)) {
			toClearOfMarkers = fieldNode.init;
			if (toClearOfMarkers instanceof JCMethodInvocation) {
				List<JCExpression> args = ((JCMethodInvocation) toClearOfMarkers).args;
				methodArgPos = new int[args.length()];
				for (int i = 0; i < methodArgPos.length; i++) {
					methodArgPos[i] = args.get(i).pos;
				}
			}
			statements = javacGetter_createLazyGetterBody(treeMaker, field, source);
			addSuppressWarningsUnchecked = LombokOptionsFactory.getDelombokOptions(field.getContext()).getFormatPreferences().generateSuppressWarnings();
		} else {
			statements = javacGetter_createSimpleGetterBody(treeMaker, field);
		}

		JCBlock methodBody = treeMaker.Block(0, statements);

		List<JCTypeParameter> methodGenericParams = List.nil();
		List<JCVariableDecl> parameters = List.nil();
		List<JCExpression> throwsClauses = List.nil();
		JCExpression annotationMethodDefaultValue = null;

		List<JCAnnotation> copyableAnnotations = findCopyableAnnotations(field);
		List<JCAnnotation> delegates = javacGetter_findDelegatesAndRemoveFromField(field);
		List<JCAnnotation> annsOnMethod = copyAnnotations(onMethod).appendList(copyableAnnotations);
		if (field.isFinal()) {
			if (getCheckerFrameworkVersion(field).generatePure()) annsOnMethod = annsOnMethod.prepend(treeMaker.Annotation(genTypeRef(field, CheckerFrameworkVersion.NAME__PURE), List.<JCExpression>nil()));
		} else {
			if (getCheckerFrameworkVersion(field).generateSideEffectFree()) annsOnMethod = annsOnMethod.prepend(treeMaker.Annotation(genTypeRef(field, CheckerFrameworkVersion.NAME__SIDE_EFFECT_FREE), List.<JCExpression>nil()));
		}
		if (isFieldDeprecated(field)) annsOnMethod = annsOnMethod.prepend(treeMaker.Annotation(genJavaLangTypeRef(field, "Deprecated"), List.<JCExpression>nil()));

		if (makeFinal) access |= Flags.FINAL;
		JCTree.JCMethodDecl decl = recursiveSetGeneratedBy(treeMaker.MethodDef(treeMaker.Modifiers(access, annsOnMethod), methodName, methodType,
			methodGenericParams, parameters, throwsClauses, methodBody, annotationMethodDefaultValue), source);

		if (toClearOfMarkers != null) recursiveSetGeneratedBy(toClearOfMarkers, null);
		if (methodArgPos != null) {
			for (int i = 0; i < methodArgPos.length; i++) {
				((JCMethodInvocation) toClearOfMarkers).args.get(i).pos = methodArgPos[i];
			}
		}
		decl.mods.annotations = decl.mods.annotations.appendList(delegates);
		if (addSuppressWarningsUnchecked) {
			ListBuffer<JCExpression> suppressions = new ListBuffer<JCExpression>();
			if (!Boolean.FALSE.equals(field.getAst().readConfiguration(ConfigurationKeys.ADD_SUPPRESSWARNINGS_ANNOTATIONS))) {
				suppressions.append(treeMaker.Literal("all"));
			}
			suppressions.append(treeMaker.Literal("unchecked"));
			addAnnotation(decl.mods, field, source, "java.lang.SuppressWarnings", treeMaker.NewArray(null, List.<JCExpression>nil(), suppressions.toList()));
		}

		copyJavadoc(field, decl, CopyJavadoc.GETTER);
		return decl;
	}

public List<JCAnnotation> javacGetter_findDelegatesAndRemoveFromField(JavacNode field) {
		JCVariableDecl fieldNode = (JCVariableDecl) field.get();

		List<JCAnnotation> delegates = List.nil();
		for (JCAnnotation annotation : fieldNode.mods.annotations) {
			if (typeMatches(Delegate.class, field, annotation.annotationType)) {
				delegates = delegates.append(annotation);
			}
		}

		if (!delegates.isEmpty()) {
			ListBuffer<JCAnnotation> withoutDelegates = new ListBuffer<JCAnnotation>();
			for (JCAnnotation annotation : fieldNode.mods.annotations) {
				if (!delegates.contains(annotation)) {
					withoutDelegates.append(annotation);
				}
			}
			fieldNode.mods.annotations = withoutDelegates.toList();
			field.rebuild();
		}
		return delegates;
	}

public List<JCStatement> javacGetter_createSimpleGetterBody(JavacTreeMaker treeMaker, JavacNode field) {
		return List.<JCStatement>of(treeMaker.Return(createFieldAccessor(treeMaker, field, FieldAccess.ALWAYS_FIELD)));
	}

public List<JCStatement> javacGetter_createLazyGetterBody(JavacTreeMaker maker, JavacNode fieldNode, JavacNode source) {
		/*
		java.lang.Object value = this.fieldName.get();
		if (value == null) {
			synchronized (this.fieldName) {
				value = this.fieldName.get();
				if (value == null) {
					final RawValueType actualValue = INITIALIZER_EXPRESSION;
					[IF PRIMITIVE]
					value = actualValue;
					[ELSE]
					value = actualValue == null ? this.fieldName : actualValue;
					[END IF]
					this.fieldName.set(value);
				}
			}
		}
		[IF PRIMITIVE]
		return (BoxedValueType) value;
		[ELSE]
		return (BoxedValueType) (value == this.fieldName ? null : value);
		[END IF]
		*/

		ListBuffer<JCStatement> statements = new ListBuffer<JCStatement>();

		JCVariableDecl field = (JCVariableDecl) fieldNode.get();
		JCExpression copyOfRawFieldType = javacGetter_copyType(maker, field, source);
		JCExpression copyOfBoxedFieldType = null;
		field.type = null;
		boolean isPrimitive = false;
		if (field.vartype instanceof JCPrimitiveTypeTree) {
			String boxed = HandleGetter.TYPE_MAP.get(typeTag(field.vartype));
			if (boxed != null) {
				isPrimitive = true;
				field.vartype = genJavaLangTypeRef(fieldNode, boxed);
				copyOfBoxedFieldType = genJavaLangTypeRef(fieldNode, boxed);
			}
		}
		if (copyOfBoxedFieldType == null) copyOfBoxedFieldType = javacGetter_copyType(maker, field, source);

		Name valueName = fieldNode.toName("value");
		Name actualValueName = fieldNode.toName("actualValue");

		/* java.lang.Object value = this.fieldName.get();*/ {
			JCExpression valueVarType = genJavaLangTypeRef(fieldNode, "Object");
			statements.append(maker.VarDef(maker.Modifiers(0L), valueName, valueVarType, javacGetter_callGet(fieldNode, createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD))));
		}

		/* if (value == null) { */ {
			JCSynchronized synchronizedStatement;
			/* synchronized (this.fieldName) { */ {
				ListBuffer<JCStatement> synchronizedStatements = new ListBuffer<JCStatement>();
				/* value = this.fieldName.get(); */ {
					JCExpressionStatement newAssign = maker.Exec(maker.Assign(maker.Ident(valueName), javacGetter_callGet(fieldNode, createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD))));
					synchronizedStatements.append(newAssign);
				}

				/* if (value == null) { */ {
					ListBuffer<JCStatement> innerIfStatements = new ListBuffer<JCStatement>();
					/* final RawValueType actualValue = INITIALIZER_EXPRESSION; */ {
						innerIfStatements.append(maker.VarDef(maker.Modifiers(Flags.FINAL), actualValueName, copyOfRawFieldType, field.init));
					}
					/* [IF primitive] value = actualValue; */ {
						if (isPrimitive) {
							JCStatement statement = maker.Exec(maker.Assign(maker.Ident(valueName), maker.Ident(actualValueName)));
							innerIfStatements.append(statement);
						}
					}
					/* [ELSE] value = actualValue == null ? this.fieldName : actualValue; */ {
						if (!isPrimitive) {
							JCExpression actualValueIsNull = maker.Binary(CTC_EQUAL, maker.Ident(actualValueName), maker.Literal(CTC_BOT, null));
							JCExpression thisDotFieldName = createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD);
							JCExpression ternary = maker.Conditional(actualValueIsNull, thisDotFieldName, maker.Ident(actualValueName));
							JCStatement statement = maker.Exec(maker.Assign(maker.Ident(valueName), ternary));
							innerIfStatements.append(statement);
						}
					}
					/* this.fieldName.set(value); */ {
						JCStatement statement = javacGetter_callSet(fieldNode, createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD), maker.Ident(valueName));
						innerIfStatements.append(statement);
					}

					JCBinary isNull = maker.Binary(CTC_EQUAL, maker.Ident(valueName), maker.Literal(CTC_BOT, null));
					JCIf ifStatement = maker.If(isNull, maker.Block(0, innerIfStatements.toList()), null);
					synchronizedStatements.append(ifStatement);
				}

				synchronizedStatement = maker.Synchronized(createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD), maker.Block(0, synchronizedStatements.toList()));
			}

			JCBinary isNull = maker.Binary(CTC_EQUAL, maker.Ident(valueName), maker.Literal(CTC_BOT, null));
			JCIf ifStatement = maker.If(isNull, maker.Block(0, List.<JCStatement>of(synchronizedStatement)), null);
			statements.append(ifStatement);
		}
		/* [IF PRIMITIVE] return (BoxedValueType) value; */ {
			if (isPrimitive) {
				statements.append(maker.Return(maker.TypeCast(copyOfBoxedFieldType, maker.Ident(valueName))));
			}
		}
		/* [ELSE] return (BoxedValueType) (value == this.fieldName ? null : value); */ {
			if (!isPrimitive) {
				JCExpression valueEqualsSelf = maker.Binary(CTC_EQUAL, maker.Ident(valueName), createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD));
				JCExpression ternary = maker.Conditional(valueEqualsSelf, maker.Literal(CTC_BOT,  null), maker.Ident(valueName));
				JCExpression typeCast = maker.TypeCast(copyOfBoxedFieldType, maker.Parens(ternary));
				statements.append(maker.Return(typeCast));
			}
		}

		// update the field type and init last

		/*	private final java.util.concurrent.atomic.AtomicReference<Object> fieldName = new java.util.concurrent.atomic.AtomicReference<Object>(); */ {
			field.vartype = recursiveSetGeneratedBy(
				maker.TypeApply(chainDotsString(fieldNode, AR), List.<JCExpression>of(genJavaLangTypeRef(fieldNode, "Object"))), source);
			field.init = recursiveSetGeneratedBy(maker.NewClass(null, NIL_EXPRESSION, javacGetter_copyType(maker, field, source), NIL_EXPRESSION, null), source);
		}

		return statements.toList();
	}

public JCMethodInvocation javacGetter_callGet(JavacNode source, JCExpression receiver) {
		JavacTreeMaker maker = source.getTreeMaker();
		return maker.Apply(NIL_EXPRESSION, maker.Select(receiver, source.toName("get")), NIL_EXPRESSION);
	}

public JCStatement javacGetter_callSet(JavacNode source, JCExpression receiver, JCExpression value) {
		JavacTreeMaker maker = source.getTreeMaker();
		return maker.Exec(maker.Apply(NIL_EXPRESSION, maker.Select(receiver, source.toName("set")), List.<JCExpression>of(value)));
	}

public JCExpression javacGetter_copyType(JavacTreeMaker treeMaker, JCVariableDecl fieldNode, JavacNode source) {
		return fieldNode.type != null ? treeMaker.Type(fieldNode.type) : cloneType(treeMaker, fieldNode.vartype, source);
	}

public void javacSetter_generateSetterForType(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelSetter, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		if (checkForTypeLevelSetter) {
			if (hasAnnotation(Setter.class, typeNode)) {
				//The annotation will make it happen, so we can skip it.
				return;
